function cachedRecommendation(){const key=JSON.stringify([today(),state.restDays,state.books.filter(b=>b.mode==='sequence').map(b=>[b.id,b.status,b.order,b.page,b.total,b.basis,b.deadline,b.dailyPages])]);if(key!==recommendationCache.key){recommendationCache={key,value:recommendation(state.books,today(),state.restDays)}}return recommendationCache.value}
