function scheduleLabel(b){if(!isDaily(b))return short(b.deadline)+'까지';let last=displayIndex.finishes.get(b.id)||'';return `하루 ${b.dailyPages}쪽 · ${last>=today()?'예상 '+short(last)+' 완독':'진도 확인 후 일정 갱신'}`}
function missedHTML(){let misses=deadlineMisses(state.books,state.alloc);if(!misses.length)return '';return `<div class="note"><strong>목표일을 넘길 수 있어요</strong>${misses.map(({book,finish})=>`<div>${esc(book.title)} · 목표 ${short(book.deadline)} / 예상 ${short(finish)}</div>`).join('')}<div class="small">하루 분량은 자동으로 늘리지 않아요. 순서를 바꾸거나 계획을 편집해 주세요.</div></div>`}
function card(b){return `<article class="book" data-book="${b.id}"><div class="book-content"><div class="bookrow">${b.status!=='done'?`<button class="handle" data-handle="${b.id}" aria-label="${esc(b.title)} 끌어서 그룹 또는 순서 변경. 편집 메뉴에서도 변경 가능">⠿</button>`:''}<span class="spine" style="background:${b.color}"></span><button class="bookbody" data-action="expand" data-id="${b.id}" aria-expanded="${expanded.has(b.id)}"><strong>${esc(b.title)}</strong><small>${b.page} / ${b.total}쪽 · ${b.status==='done'?short(b.finished)+' 완독':b.status==='past'?b.reason:scheduleLabel(b)} ${expanded.has(b.id)?'⌃':'⌄'}</small></button><button class="icon" data-action="menu" data-id="${b.id}" aria-label="${esc(b.title)} 관리">⋯</button></div><div class="progress"><i style="width:${b.page/b.total*100}%;background:${b.color}"></i></div>${expanded.has(b.id)?graphHTML(b):''}</div></article>`}
