document.addEventListener('click',e=>{const button=e.target.closest('[data-rest-weekday],[data-rest-remove]');if(!button)return;const config=normalizeRestDays(state.restDays);if(button.dataset.restWeekday!=null){const day=Number(button.dataset.restWeekday);config.weekdays=config.weekdays.includes(day)?config.weekdays.filter(d=>d!==day):[...config.weekdays,day]}else delete config.dates[button.dataset.restRemove];applyRestDays(config)});
