function calendarDetailsHTML(){let list=(displayIndex.dates.get(selected)||[]),sum=list.reduce((s,a)=>s+a.n,0);let html=`<section class="sectionline"><div class="row"><h2 style="font-size:16px">${short(selected)} · ${selected===today()?'오늘의 독서':'독서 계획'}</h2><span class="pill">총 ${sum}쪽</span></div><p class="summary">${sum?`예상 약 ${Math.floor(sum*2/60)?Math.floor(sum*2/60)+'시간 ':''}${sum*2%60?sum*2%60+'분':''} <span class="small">· 시간당 30쪽 기준</span>`:'나의 속도로, 한 페이지씩.'}</p>${list.map(a=>{let b=get(a.id);return `<div class="book"><button class="bookrow wide" data-action="record" data-id="${b.id}"><span class="spine" style="background:${b.color}"></span><span class="bookbody"><strong>${esc(b.title)}</strong><small>${a.from}–${a.to}쪽 · ${isDaily(b)?'하루 분량 기준':'목표일 기준'}</small></span><span class="pill">${a.n}쪽</span><span>›</span></button></div>`}).join('')||(isRestDay(selected,state.restDays)?'<div class="empty">쉬는 날이에요.<br>원하면 독서 계획에서 진도를 기록할 수 있어요.</div>':'<div class="empty"><div class="symbol">▧</div>이 날짜에는 예정된 독서가 없어요.<br>책 한 권으로 시작해 보세요.</div>')}${sum>=60?'<div class="note">독서에 충분한 시간을 확보하면 좋아요.<br>목표일은 언제든 변경할 수 있어요.</div>':''}</section>`;if(unmet().length)html+='<button class="note wide" data-action="check">확인하지 않은 진도가 있어요 · 확인하기 →</button>';if(!state.books.length)html+='<button class="primary wide add" data-action="new">＋ 첫 독서 계획 만들기</button>';return html;}
