 if(tab==='timer'){html=timerHTML()}else if(tab==='settings'){html=settingsHTML(state.restDays)}else if(tab==='calendar'){let first=month+'-01',offset=new Date(first+'T12:00:00').getDay(),length=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();html=`<div class="row month"><button class="icon" data-action="prev" aria-label="이전 달">‹</button><h2>${month.slice(0,4)}년 ${Number(month.slice(5))}월</h2><button class="icon" data-action="next" aria-label="다음 달">›</button></div><div class="week">${'일월화수목금토'.split('').map(x=>`<span>${x}</span>`).join('')}</div><div class="grid">${Array.from({length:offset},()=>'<div class="day blank"></div>').join('')}${Array.from({length},(_,i)=>{let d=add(first,i),a=(displayIndex.dates.get(d)||[]),books=[...new Set(a.map(x=>x.id))],weekday=(offset+i)%7,holiday=holidays[d],rest=isRestDay(d,state.restDays);return `<button class="day ${rest?'day-rest':''} ${holiday||weekday===0?'day-holiday':weekday===6?'day-saturday':''} ${d===today()?'today':''} ${d===selected?'selected':''}" data-date="${d}" aria-label="${d}${rest?', 쉬는 날':''}${holiday?', '+esc(holiday.join(', ')):''}, ${books.length}권" aria-pressed="${d===selected}">${i+1}${rest?'<span class="rest-label">휴식</span>':''}<span class="marks">${books.slice(0,3).map(id=>`<i style="background:${get(id)?.color}"></i>`).join('')}${books.length>3?`<small>+${books.length-3}</small>`:''}</span></button>`}).join('')}</div>`;
 html+='<div id="calendar-details">'+calendarDetailsHTML()+'</div>';
 }else if(tab==='plans'){html='';for(const [title,group,filter] of [['순서대로 읽는 책','sequence',b=>b.status==='active'&&b.mode==='sequence'],['동시에 읽는 책','parallel',b=>b.status==='active'&&b.mode==='parallel'],['지난 계획','past',b=>b.status==='past']]){let arr=state.books.filter(filter).sort((a,b)=>a.order-b.order);html+=`<section class="plan-group" data-group="${group}"><h3>${title}<span class="count">${arr.length}권</span></h3>${arr.map(card).join('')||'<div class="empty">아직 책이 없어요.</div>'}${group==='sequence'?missedHTML()+recommendHTML():''}</section>`}}
