function updateDragVisual(){
 if(!drag?.moved)return;
 if(!drag.ghost){const ghost=drag.card.cloneNode(true);ghost.classList.remove('dragging');ghost.classList.add('drag-ghost');ghost.setAttribute('aria-hidden','true');ghost.inert=true;ghost.querySelector('.graphbox')?.remove();Object.assign(ghost.style,{width:drag.width+'px',left:'0',top:'0'});document.body.append(ghost);drag.ghost=ghost;drag.card.classList.add('dragging');document.body.classList.add('is-dragging')}
 drag.ghost.style.transform='translate3d('+(drag.x-drag.offsetX)+'px,'+(drag.y-drag.offsetY)+'px,0) rotate(1deg)';
 const target=document.elementFromPoint(drag.x,drag.y),group=target?.closest('[data-group]'),book=target?.closest('[data-book]'),source=drag.card.closest('[data-group]');
 document.querySelectorAll('[data-group]').forEach(el=>el.classList.toggle('drop-target',el===group));
 let marker=null,position=null;
 if(group===source&&group?.dataset.group==='sequence'&&book&&book!==drag.card){const cards=[...group.querySelectorAll('[data-book]')];marker=book;position=cards.indexOf(drag.card)<cards.indexOf(book)?'drop-after':'drop-before'}
 else if(group&&group!==source){marker=[...group.querySelectorAll('[data-book]')].at(-1);position='drop-after'}
 document.querySelectorAll('.drop-before,.drop-after').forEach(el=>{if(el!==marker||position!=='drop-before')el.classList.remove('drop-before');if(el!==marker||position!=='drop-after')el.classList.remove('drop-after')});
 if(marker&&position)marker.classList.add(position);
}
function dragScroll(){if(!drag)return;if(drag.moved){const edge=90,y=drag.y;let amount=y<edge?-10:y>innerHeight-edge?10:0;if(amount)window.scrollBy(0,amount);updateDragVisual()}dragFrame=requestAnimationFrame(dragScroll)}
document.addEventListener('pointerdown',e=>{let h=e.target.closest('[data-handle]');if(h&&e.isPrimary!==false&&e.button===0){const card=h.closest('.book'),rect=card.getBoundingClientRect();drag={id:h.dataset.handle,card,width:rect.width,offsetX:e.clientX-rect.left,offsetY:e.clientY-rect.top,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};h.setPointerCapture(e.pointerId);dragFrame=requestAnimationFrame(dragScroll)}});
document.addEventListener('pointermove',e=>{if(!drag)return;drag.x=e.clientX;drag.y=e.clientY;drag.moved ||= Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>8});
document.addEventListener('pointerup',e=>{if(!drag)return;let target=document.elementFromPoint(e.clientX,e.clientY),group=target?.closest('[data-group]'),book=target?.closest('[data-book]'),id=drag.id,moved=drag.moved;clearDrag();if(!moved||!group)return;let b=get(id),dest=group.dataset.group,source=b.status==='past'?'past':b.mode;if(dest===source){if(dest==='sequence'&&book)reorder(id,book.dataset.book);return}if(b.status==='past'&&dest!=='past'){form(id,true,dest);return}undo=structuredClone(state);moveBook(state,id,dest,today());save();render();toast(dest==='past'?'지난 계획으로 이동했어요.':'읽기 방식을 변경했어요.',true)});
document.addEventListener('pointercancel',clearDrag);
document.addEventListener('keydown',e=>{let h=e.target.closest('[data-handle]');if(!h||get(h.dataset.handle)?.status!=='active'||get(h.dataset.handle)?.mode!=='sequence'||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();let arr=state.books.filter(b=>b.status==='active'&&b.mode==='sequence').sort((a,b)=>a.order-b.order),i=arr.findIndex(b=>b.id===h.dataset.handle),target=arr[i+(e.key==='ArrowUp'?-1:1)];if(target)reorder(h.dataset.handle,target.id)});
function resetCalendarDate(){selected=today();month=selected.slice(0,7)}
function maybeCheckProgress(){if(!unmet().length||tab!=='calendar'||document.hidden||lastCheckDate===today()||timerIsRunning()||$('#modal').open||document.querySelector('dialog[open]'))return;check();}
function refreshAfterReturn(){if(document.hidden)return;indexDisplay();if(document.querySelector('dialog[open]')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||tab==='timer'){pendingDayRefresh ||= today()!==renderedDay;return;}resetCalendarDate();render();}
function queueDeferredDayRefresh(){if(!pendingDayRefresh)return;setTimeout(()=>{if(pendingDayRefresh&&!document.hidden&&tab==='calendar'&&!$('#modal').open&&!document.querySelector('dialog[open]')){resetCalendarDate();render()}},0)}
document.addEventListener('close',e=>{if(e.target.id==='modal')queueDeferredDayRefresh()},true);
let midnightTimer;
function scheduleMidnight(){clearTimeout(midnightTimer);const now=new Date(),next=new Date(now);next.setHours(24,0,0,50);midnightTimer=setTimeout(()=>{refreshAfterReturn();scheduleMidnight()},next-now);}
render();scheduleMidnight();document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshAfterReturn();scheduleMidnight()}});
if(typeof window!=='undefined')window.addEventListener('pageshow',e=>{if(e.persisted){refreshAfterReturn();scheduleMidnight()}});

let pan=null;document.addEventListener('pointerdown',e=>{let chart=e.target.closest('.chart');if(chart&&e.pointerType==='mouse'){pan={chart,x:e.clientX,left:chart.scrollLeft};chart.setPointerCapture(e.pointerId)}});document.addEventListener('pointermove',e=>{if(pan)pan.chart.scrollLeft=pan.left-(e.clientX-pan.x)});document.addEventListener('pointerup',()=>pan=null);document.addEventListener('pointercancel',()=>pan=null);
